/**
 * Retrieve Bushu (radical) information for a given Kanji character.
 * Returns null if not found.
 */
export function getBushuByKanji(kanji: string): BushuDetail | null {
  if (!kanji) return null;
  // If a compound word was passed, try the first character or direct match
  if (KANJI_BUSHU_MAP[kanji]) {
    return KANJI_BUSHU_MAP[kanji];
  }
  for (const char of kanji) {
    if (KANJI_BUSHU_MAP[char]) {
      return KANJI_BUSHU_MAP[char];
    }
  }
  return null;
}
